<?php
/* SECURITY_V1 PATTERN_OTP_V3 */
function sec_read($f){$x=json_decode((string)@file_get_contents($f),true);return is_array($x)?$x:[];}
function sec_write($f,$x){$l=@fopen($f.'.lock','c');if(!$l||!flock($l,LOCK_EX))return false;try{$t=$f.'.tmp.'.bin2hex(random_bytes(3));$j=json_encode($x,JSON_UNESCAPED_UNICODE);if($j===false||file_put_contents($t,$j,LOCK_EX)===false)return false;@chmod($t,0640);return @rename($t,$f);}finally{flock($l,LOCK_UN);fclose($l);}}
function sec_headers(){header('X-Frame-Options: DENY');header('X-Content-Type-Options: nosniff');header('Referrer-Policy: no-referrer');header('Permissions-Policy: camera=(), microphone=(), geolocation=(), payment=()');if(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')header('Strict-Transport-Security: max-age=31536000; includeSubDomains');}
function sec_file($d){return $d.'/_login_security.json';}
function sec_secret($d){$f=$d.'/_login_secret';$s=trim((string)@file_get_contents($f));if(strlen($s)<32){$s=bin2hex(random_bytes(32));@file_put_contents($f,$s,LOCK_EX);@chmod($f,0600);}return $s;}
function sec_key($d,$v){return hash_hmac('sha256',$v,sec_secret($d));}
function sec_state($d){$s=sec_read(sec_file($d));$s['accounts']=is_array($s['accounts']??null)?$s['accounts']:[];$s['ips']=is_array($s['ips']??null)?$s['ips']:[];$s['resets']=is_array($s['resets']??null)?$s['resets']:[];$s['otp']=is_array($s['otp']??null)?$s['otp']:[];return $s;}
function sec_save($d,$s){return sec_write(sec_file($d),$s);}
function sec_ip(){return (string)($_SERVER['REMOTE_ADDR']??'0');}
function sec_can_login($d,$scope,$id){$s=sec_state($d);$a=sec_key($d,'a|'.$scope.'|'.$id);$i=sec_key($d,'i|'.sec_ip());if(!empty($s['accounts'][$a]['locked']))return false;return (int)($s['ips'][$i]['until']??0)<=time();}
function sec_fail($d,$scope,$id){$s=sec_state($d);$now=time();$a=sec_key($d,'a|'.$scope.'|'.$id);$r=$s['accounts'][$a]??['n'=>0,'last'=>0,'locked'=>false];if($now-(int)$r['last']>86400)$r['n']=0;$r['n']++;$r['last']=$now;if($r['n']>=5)$r['locked']=true;$s['accounts'][$a]=$r;$i=sec_key($d,'i|'.sec_ip());$q=$s['ips'][$i]??['n'=>0,'last'=>0,'until'=>0];if($now-(int)$q['last']>3600)$q['n']=0;$q['n']++;$q['last']=$now;if($q['n']>=15)$q['until']=$now+3600;$s['ips'][$i]=$q;sec_save($d,$s);}
function sec_success($d,$scope,$id){$s=sec_state($d);unset($s['accounts'][sec_key($d,'a|'.$scope.'|'.$id)]);$i=sec_key($d,'i|'.sec_ip());if(isset($s['ips'][$i])){$s['ips'][$i]['n']=0;$s['ips'][$i]['until']=0;}sec_save($d,$s);}
function sec_unlock($d,$scope,$id){$s=sec_state($d);unset($s['accounts'][sec_key($d,'a|'.$scope.'|'.$id)]);sec_save($d,$s);}
function sec_mobile($m){$m=preg_replace('/\D/','',(string)$m)??'';if(str_starts_with($m,'98'))$m='0'.substr($m,2);if(strlen($m)===10&&str_starts_with($m,'9'))$m='0'.$m;return $m;}
function sec_sender($s){$s=trim((string)$s);if($s===''||str_starts_with($s,'+'))return $s;$d=preg_replace('/\D/','',$s)??'';if($d===''||$d!==$s)return $s;if(str_starts_with($d,'00'))return '+'.substr($d,2);if(str_starts_with($d,'98'))return '+'.$d;if(str_starts_with($d,'0'))return '+98'.substr($d,1);return '+98'.$d;}
function sec_reset_allowed($d,$scope,$id){$s=sec_state($d);$now=time();foreach([sec_key($d,'ri|'.sec_ip()),sec_key($d,'ra|'.$scope.'|'.$id)] as $k){$r=$s['resets'][$k]??['n'=>0,'start'=>$now];if($now-(int)$r['start']>=3600)$r=['n'=>0,'start'=>$now];if((int)$r['n']>=3){sec_save($d,$s);return false;}$r['n']++;$s['resets'][$k]=$r;}sec_save($d,$s);return true;}
function sec_sms_key(array $c):string{$key='';foreach(['sms_api_key','faraz_api_key','ippanel_api_key','api_key'] as $k){if(trim((string)($c[$k]??''))!==''){$key=trim((string)$c[$k]);break;}}if($key==='')foreach(['FARAZ_SMS_API_KEY','IPPANEL_API_KEY','SMS_API_KEY'] as $k){$v=getenv($k);if(is_string($v)&&trim($v)!==''){$key=trim($v);break;}}return $key;}
function sec_sms_log($settingsFile,$type,$http,$body,$sender,$pattern=''){ $j=json_decode((string)$body,true);$safe=['at'=>date('c'),'type'=>$type,'http'=>(int)$http,'sender'=>$sender,'pattern'=>$pattern];if(is_array($j)){$safe['status']=$j['meta']['status']??null;$safe['message']=$j['meta']['message']??'';$safe['message_code']=$j['meta']['message_code']??'';}else{$safe['response']=mb_substr((string)$body,0,500);} @file_put_contents(dirname($settingsFile).'/sms_last_provider.json',json_encode($safe,JSON_UNESCAPED_UNICODE),LOCK_EX);@chmod(dirname($settingsFile).'/sms_last_provider.json',0600);}
function sec_sms($settingsFile,$mobile,$message){$c=sec_read($settingsFile);if(empty($c['sms_enabled'])&&array_key_exists('sms_enabled',$c))return false;$key=sec_sms_key($c);$m=sec_mobile($mobile);if($key===''||!preg_match('/^09\d{9}$/',$m)||!function_exists('curl_init'))return false;$to='+98'.substr($m,1);$from=sec_sender($c['sms_sender']??'90008361');$url=trim((string)($c['sms_api_endpoint']??'https://edge.ippanel.com/v1/api/send'));$payload=['sending_type'=>'webservice','from_number'=>$from,'message'=>$message,'params'=>['recipients'=>[$to]]];$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($payload,JSON_UNESCAPED_UNICODE),CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: '.$key],CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>6,CURLOPT_TIMEOUT=>12]);$body=(string)curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);sec_sms_log($settingsFile,'webservice',$code,$body,$from);if($code<200||$code>=300)return false;if($body!==''){$j=json_decode($body,true);if(is_array($j)&&isset($j['meta']['status'])&&$j['meta']['status']===false)return false;}return true;}
function sec_sms_pattern($settingsFile,$mobile,$pattern,$params){$c=sec_read($settingsFile);if(empty($c['sms_enabled'])&&array_key_exists('sms_enabled',$c))return false;$key=sec_sms_key($c);$m=sec_mobile($mobile);$pattern=trim((string)$pattern);if($key===''||!preg_match('/^09\d{9}$/',$m)||$pattern===''||!function_exists('curl_init'))return false;$to='+98'.substr($m,1);$from=sec_sender($c['sms_sender']??'90008361');$url=trim((string)($c['sms_api_endpoint']??'https://edge.ippanel.com/v1/api/send'));$payload=['sending_type'=>'pattern','from_number'=>$from,'code'=>$pattern,'recipients'=>[$to],'params'=>(object)$params];$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($payload,JSON_UNESCAPED_UNICODE),CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: '.$key],CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>6,CURLOPT_TIMEOUT=>12]);$body=(string)curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);sec_sms_log($settingsFile,'pattern',$code,$body,$from,$pattern);if($code<200||$code>=300)return false;if($body!==''){$j=json_decode($body,true);if(is_array($j)&&isset($j['meta']['status'])&&$j['meta']['status']===false)return false;}return true;}
function sec_issue_code($d,$scope,$id,$mobile,$settingsFile){if(!sec_reset_allowed($d,$scope,$id))return false;$code=(string)random_int(100000,999999);$s=sec_state($d);$k=sec_key($d,'otp|'.$scope.'|'.$id);$s['otp'][$k]=['hash'=>password_hash($code,PASSWORD_DEFAULT),'until'=>time()+300,'tries'=>0];if(!sec_save($d,$s))return false;$c=sec_read($settingsFile);$pattern=trim((string)($c['sms_recovery_pattern']??'xa2lAXeEHs'));$sent=sec_sms_pattern($settingsFile,$mobile,$pattern,['code'=>$code]);if(!$sent){unset($s['otp'][$k]);sec_save($d,$s);return false;}return true;}
function sec_verify_code($d,$scope,$id,$code){$s=sec_state($d);$k=sec_key($d,'otp|'.$scope.'|'.$id);$r=$s['otp'][$k]??null;if(!is_array($r)||(int)($r['until']??0)<time()||(int)($r['tries']??0)>=5)return false;$ok=password_verify((string)$code,(string)($r['hash']??''));if($ok)unset($s['otp'][$k]);else{$r['tries']=(int)($r['tries']??0)+1;$s['otp'][$k]=$r;}sec_save($d,$s);return $ok;}
function sec_harden_admin($adminFile,$settingsFile,$d){$a=sec_read($adminFile);if(!$a)return;$changed=false;$h=(string)($a['password_hash']??'');if($h===''||password_verify('123456',$h)){$a['password_hash']=password_hash(bin2hex(random_bytes(32)),PASSWORD_DEFAULT);$a['must_change']=true;$changed=true;for($i=0;$i<5;$i++)sec_fail($d,'admin','root');}if(empty($a['mobile'])){$c=sec_read($settingsFile);$m=sec_mobile((string)($c['sms_manager_mobile']??''));if(preg_match('/^09\d{9}$/',$m)){$a['mobile']=$m;$changed=true;}}if($changed)sec_write($adminFile,$a);}
